        </button>

        {step === 'form' && (
          <motion.div initial={{ y: 20 }} animate={{ y: 0 }} className="bg-slate-50 rounded-3xl shadow-2xl w-full max-w-lg overflow-hidden border-t-[12px] border-blue-900 my-8">
