              <div className="flex items-center gap-4">
                <div className="w-14 h-14 bg-white rounded-full flex items-center justify-center font-black text-blue-900 text-3xl border-2 border-yellow-500 shadow-lg">U</div>
                <div>
                  <h2 className="text-white font-black text-xl uppercase tracking-tighter">Imperial Central</h2>
                  <p className="text-blue-300 text-[10px] font-mono tracking-widest">FACULTY SERVER V2.4</p>
                </div>
              </div>
            </div>

            <form onSubmit={handleStartCheck} className="p-8 space-y-8">
              <div className="flex justify-between items-center bg-blue-50 p-4 rounded-2xl border border-blue-100">
                <span className="text-xs font-black text-blue-900 uppercase">Group Verification</span>
                <button type="button" onClick={() => setIsGroupMode(!isGroupMode)} className={`w-14 h-7 rounded-full transition-all relative ${isGroupMode ? 'bg-blue-600' : 'bg-slate-300'}`}>
                   <div className={`absolute top-1.5 w-4 h-4 bg-white rounded-full transition-all ${isGroupMode ? 'left-8' : 'left-1.5'} shadow-md`} />
                </button>
              </div>

              <div className="space-y-6 max-h-[45vh] overflow-y-auto pr-2 no-scrollbar">
                {students.map((student, idx) => (
                  <div key={idx} className="p-6 bg-white border border-slate-200 rounded-2xl space-y-4 relative shadow-sm">
                    {idx > 0 && <button onClick={() => setStudents(students.filter((_, i) => i !== idx))} className="absolute top-4 right-4 text-red-500 font-bold text-[10px]">REMOVE</button>}
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                      <div>
                        <label className="block text-[10px] font-black text-slate-400 uppercase mb-1">Full Name</label>
                        <input required type="text" value={student.name} onChange={e => { const n = [...students]; n[idx].name = e.target.value; setStudents(n); }} className="w-full border-b-2 border-slate-200 py-1 focus:border-blue-900 outline-none text-sm text-black bg-transparent" />
                      </div>
                      <div>
                        <label className="block text-[10px] font-black text-slate-400 uppercase mb-1">Student ID</label>
                        <input required type="text" value={student.id} onChange={e => { const n = [...students]; n[idx].id = e.target.value; setStudents(n); }} className="w-full border-b-2 border-slate-200 py-1 focus:border-blue-900 outline-none text-sm text-black bg-transparent" />
                      </div>
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                      <div className="space-y-1">
                        <label className="block text-[10px] font-black text-slate-400 uppercase">Total</label>
                        <input required type="number" value={student.total || ''} onChange={e => { const n = [...students]; n[idx].total = parseInt(e.target.value) || 0; setStudents(n); }} className="w-full bg-slate-100 border-none p-3 rounded-xl text-sm text-black font-bold" />
                      </div>
                      <div className="space-y-1">
                        <label className="block text-[10px] font-black text-slate-400 uppercase">Present</label>
                        <input required type="number" value={student.attended || ''} onChange={e => { const n = [...students]; n[idx].attended = parseInt(e.target.value) || 0; setStudents(n); }} className="w-full bg-slate-100 border-none p-3 rounded-xl text-sm text-black font-bold" />
                      </div>
                    </div>
                  </div>
                ))}
              </div>

              {isGroupMode && (
                <button type="button" onClick={() => setStudents([...students, { name: '', id: '', total: 0, attended: 0, pct: 0, status: 'Detained' }])} className="w-full py-4 border-2 border-dashed border-slate-300 text-slate-400 text-xs font-black hover:bg-slate-50 rounded-2xl transition-colors">
                  + ADD CLASSMATE
                </button>
              )}

              <button type="submit" className="w-full bg-blue-900 text-white font-black py-5 rounded-2xl shadow-2xl shadow-blue-900/40 hover:bg-blue-800 transition-all flex items-center justify-center gap-3 active:scale-95">
                VERIFY LOGS
              </button>
            </form>
          </motion.div>
        )}

        {step === 'loading' && (
          <div className="max-w-md w-full text-center space-y-10 p-10">
            <div className="relative inline-block">
              <div className="w-40 h-40 border-8 border-cyan-500/10 border-t-cyan-500 rounded-full animate-spin mx-auto"></div>
              <div className="absolute inset-0 flex items-center justify-center font-black text-cyan-400 text-2xl">
                {Math.floor((teacherMsgIndex / TEACHER_LINES.length) * 100)}%
              </div>
            </div>
            <div className="space-y-4">
              <h2 className="text-white font-black text-2xl tracking-widest uppercase animate-pulse">Scanning Bio-Logs</h2>
              <div className="bg-slate-900/80 p-6 rounded-3xl border border-slate-700 text-left font-mono text-[11px] space-y-2 backdrop-blur-xl">
                {TEACHER_LINES.slice(0, teacherMsgIndex + 1).map((line, i) => (
                  <div key={i} className="text-cyan-400 flex gap-2">
                    <span className="opacity-40">{new Date().toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}</span>
                    <span>{line}</span>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}

        {step === 'result' && (
          <div className="max-w-5xl w-full space-y-10 py-16 px-2">
            <h1 className="text-white text-4xl sm:text-5xl font-black text-center mb-12 uppercase tracking-[0.3em]">The Verdict</h1>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
              {students.map((s, idx) => (
                <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} transition={{ delay: idx * 0.1 }} key={idx} className={`bg-white p-8 rounded-3xl shadow-2xl relative border-b-[10px] ${s.status === 'Detained' ? 'border-red-600' : 'border-green-600'}`}>
                  <div className="mb-6">
                      <h3 className="font-black text-slate-800 text-2xl truncate">{s.name || 'Anonymous'}</h3>
                      <p className="text-[10px] font-mono text-slate-400 font-bold uppercase tracking-widest">Auth Token: {s.id || 'N/A'}</p>
