                    <div className="w-full h-5 bg-slate-100 rounded-full relative overflow-hidden">
                      <motion.div initial={{ width: 0 }} animate={{ width: `${s.pct}%` }} transition={{ duration: 1.5 }} className={`h-full ${s.pct < 75 ? 'bg-red-500' : 'bg-green-500'}`} />
                      <div className="absolute top-0 left-[75%] w-1 h-full bg-slate-900/10 z-10" />
                    </div>
                  </div>

                  {s.status === 'Detained' ? (
                    <div className="space-y-4">
                      <div className="p-4 bg-red-50 border border-red-100 rounded-2xl text-red-700 text-xs font-bold leading-tight uppercase tracking-tight italic">
