                      </div>
                      <button onClick={() => setStep('game')} className="w-full py-4 bg-slate-900 text-white text-xs font-black rounded-2xl uppercase hover:bg-black transition-all active:scale-95">
                        Initiate Mercy Appeal
                      </button>
                    </div>
                  ) : (
                    <div className="p-4 bg-green-50 border border-green-100 rounded-2xl text-green-700 text-xs font-black uppercase tracking-tight italic text-center">
                        "ELIGIBILITY CONFIRMED."
                    </div>
                  )}
                </motion.div>
              ))}
            </div>

            {students.some(s => s.pct < 75) && (
              <div className="mt-12 p-8 bg-slate-900/50 border border-slate-800 rounded-3xl backdrop-blur-xl">
                 <h4 className="text-slate-400 font-black mb-6 uppercase text-center text-sm tracking-widest">System Override: Excuse Portal</h4>
                 <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
