                      <button key={e.label} onClick={() => handleSelectExcuse(e.result)} className="p-4 bg-black/40 border border-slate-700 text-slate-300 text-xs font-bold rounded-2xl hover:border-red-500 hover:text-red-400 transition-all text-left">
