             <div className="text-center space-y-2">
                <h2 className="text-4xl font-black text-white uppercase tracking-tighter">Detainment Dodge</h2>
                <p className="text-slate-500 text-sm font-bold uppercase tracking-widest">Survive the assignment avalanche</p>
