                      </>
                    )}
                    {gameState === 'lost' && (
                      <>
                        <h3 className="text-red-600 text-6xl font-black uppercase">F-Grade</h3>
                        <p className="text-white font-bold">You were buried by assignments. Detainment upheld.</p>
                        <button onClick={() => setGameState('idle')} className="text-cyan-500 font-black border-b-2 border-cyan-500 uppercase tracking-widest py-1">Try Again</button>
                      </>
                    )}
                    {gameState === 'won' && (
                      <>
                        <h3 className="text-green-500 text-6xl font-black uppercase italic">Phew!</h3>
                        <p className="text-white font-bold">You survived the load! Your attendance has been recalibrated to...</p>
                        <div className="text-7xl font-black text-red-500 animate-bounce">74.9%</div>
                        <p className="text-slate-500 font-black text-xs uppercase">"System Limitation: Still Failing."</p>
                        <button onClick={() => setStep('result')} className="bg-white text-black px-10 py-4 rounded-full font-black uppercase text-sm">Return to Logs</button>
                      </>
                    )}
                  </div>
                )}
             </div>
             <button onClick={() => setStep('result')} className="text-slate-600 font-black uppercase text-xs tracking-[0.3em] hover:text-white transition-colors">Abort Portal</button>
          </div>
        )}

        <AnimatePresence>
          {showFakeCall && (
            <motion.div initial={{ y: '100%' }} animate={{ y: 0 }} exit={{ y: '100%' }} className="fixed bottom-0 left-0 right-0 bg-slate-900 border-t-2 border-slate-700 p-8 z-[200000] flex flex-col sm:flex-row items-center justify-between shadow-[0_-20px_50px_rgba(0,0,0,0.5)] gap-6 rounded-t-[3rem]">
              {callStatus === 'incoming' ? (
                <>
                  <div className="flex items-center gap-6 w-full sm:w-auto">
                    <div className="w-16 h-16 bg-red-500/20 rounded-full flex items-center justify-center text-3xl animate-pulse ring-8 ring-red-500/10">📞</div>
                    <div>
                      <h4 className="text-white font-black text-2xl tracking-tighter">HOD OFFICE</h4>
                      <p className="text-red-500 text-xs font-black uppercase tracking-widest">Urgent Review</p>
                    </div>
                  </div>
                  <div className="flex gap-8 w-full sm:w-auto justify-center">
                    <button onClick={() => setShowFakeCall(false)} className="w-16 h-16 rounded-full bg-red-600 flex items-center justify-center shadow-xl shadow-red-600/30 active:scale-90 transition-transform"><svg className="w-8 h-8 text-white" fill="currentColor" viewBox="0 0 20 20"><path d="M10 18a8 8 0 100-16 8 8 0 000 16zM7 9a1 1 0 000 2h6a1 1 0 100-2H7z"/></svg></button>
                    <button onClick={async () => { setCallStatus('connected'); stopAllSounds(); await playHODVoice(); setTimeout(() => setShowFakeCall(false), 9000); }} className="w-16 h-16 rounded-full bg-green-500 flex items-center justify-center animate-bounce shadow-xl shadow-green-500/30 active:scale-90 transition-transform"><svg className="w-8 h-8 text-white" fill="currentColor" viewBox="0 0 20 20"><path d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z"/></svg></button>
                  </div>
                </>
              ) : (
                <div className="w-full flex items-center justify-center py-6">
                   <div className="text-center space-y-2">
                      <h4 className="text-green-400 font-black text-xs tracking-[0.4em] uppercase">Encrypted Connection Established</h4>
                      <p className="text-white text-xl font-black uppercase animate-pulse">FACULTY STREAM ACTIVE</p>
                   </div>
                </div>
              )}
            </motion.div>
          )}
        </AnimatePresence>
      </motion.div>
    </AnimatePresence>
  );
}

import React, { useEffect, useState } from 'react';
import { createPortal } from 'react-dom';
import { motion, AnimatePresence } from 'framer-motion';

interface ModalProps {
  isOpen: boolean;
  onClose: () => void;
  title: string;
  children: React.ReactNode;
}

export const Modal: React.FC<ModalProps> = ({ isOpen, onClose, title, children }) => {
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
    if (isOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
    return () => {
      document.body.style.overflow = 'unset';
    };
  }, [isOpen]);

  if (!mounted) return null;

  return createPortal(
    <AnimatePresence>
      {isOpen && (
        <div className="fixed inset-0 z-[99999] flex items-center justify-center p-4 sm:p-6 overflow-hidden">
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={onClose}
            className="absolute inset-0 bg-black/80 backdrop-blur-xl"
          />
          <motion.div
            initial={{ scale: 0.9, opacity: 0, y: 20 }}
            animate={{ scale: 1, opacity: 1, y: 0 }}
            exit={{ scale: 0.9, opacity: 0, y: 20 }}
            transition={{ type: "spring", duration: 0.6, bounce: 0.2 }}
            className="relative w-full max-w-lg bg-slate-900 border border-slate-700 rounded-3xl shadow-2xl overflow-hidden flex flex-col max-h-[90dvh] z-10"
          >
            <div className="flex justify-between items-center px-6 py-5 border-b border-slate-800 bg-slate-900/50 backdrop-blur-xl flex-shrink-0">
              <h3 className="text-xl font-black text-white tracking-tight uppercase">{title}</h3>
              <button 
                  onClick={onClose} 
                  className="p-2 rounded-xl hover:bg-slate-800 text-slate-500 hover:text-white transition-all active:scale-90"
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>
            </div>
            <div className="p-6 overflow-y-auto scroll-container overscroll-contain no-scrollbar flex-1">
              {children}
            </div>
          </motion.div>
        </div>
      )}
    </AnimatePresence>,
    document.body
  );
};

import React, { useState, useEffect, useMemo, useRef, useCallback } from 'react';
import { motion, AnimatePresence, useSpring } from 'framer-motion';
import { AttendanceState, AttendanceStats } from '../types';
import { calculateStats } from '../utils/calculations';
import { Modal } from './Modal';
import { Calendar } from './Calendar';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, ReferenceLine } from 'recharts';

const AnimatedCounter: React.FC<{ value: number; className?: string; toFixed?: number }> = React.memo(({ value, className, toFixed = 0 }) => {
  const ref = useRef<HTMLSpanElement>(null);
  const springValue = useSpring(value, { stiffness: 60, damping: 20 });

  useEffect(() => {
    springValue.set(value);
  }, [value, springValue]);

  useEffect(() => {
    return springValue.on("change", (latest) => {
      if (ref.current) {
        ref.current.textContent = latest.toFixed(toFixed);
      }
    });
  }, [springValue, toFixed]);

  return <span ref={ref} className={className}>{value.toFixed(toFixed)}</span>;
});

export const Dashboard: React.FC = () => {
  const [state, setState] = useState<AttendanceState>({
    totalClasses: 0,
    absentClasses: 0,
    examDate: '',
    holidays: [],
    extraWorkingDays: []
  });

  const [stats, setStats] = useState<AttendanceStats | null>(null);
  const [isHolidayModalOpen, setIsHolidayModalOpen] = useState(false);
  const [inputMode, setInputMode] = useState<'absent' | 'present'>('absent');

  useEffect(() => {
    setStats(calculateStats(state));
  }, [state]);

  const handleChange = useCallback((field: keyof AttendanceState, value: any) => {
    setState(prev => {
        const newState = { ...prev, [field]: value };

        if (field === 'totalClasses') {
            const newTotal = Math.max(0, Number(value));
            newState.totalClasses = newTotal;
            if (newState.absentClasses > newTotal) {
                newState.absentClasses = newTotal;
            }
        } else if (field === 'absentClasses') {
            const newAbsent = Math.max(0, Number(value));
            if (newAbsent > newState.totalClasses) {
                newState.absentClasses = newState.totalClasses;
            } else {
                newState.absentClasses = newAbsent;
            }
        }

        return newState;
    });
  }, []);

  const handleAttendanceChange = (val: number) => {
    if (inputMode === 'absent') {
      handleChange('absentClasses', val);
    } else {
      const currentTotal = state.totalClasses;
      const validPresent = Math.min(Math.max(0, val), currentTotal);
      const newAbsent = currentTotal - validPresent;
      handleChange('absentClasses', newAbsent);
    }
  };

  const toggleHoliday = useCallback((date: string, isWeekend: boolean) => {
    setState(prev => {
        if (isWeekend) {
            const isWorking = prev.extraWorkingDays.includes(date);
            if (isWorking) {
                return { ...prev, extraWorkingDays: prev.extraWorkingDays.filter(d => d !== date) };
            } else {
                return { ...prev, extraWorkingDays: [...prev.extraWorkingDays, date] };
            }
        } else {
            const isHoliday = prev.holidays.includes(date);
            if (isHoliday) {
                return { ...prev, holidays: prev.holidays.filter(d => d !== date) };
            } else {
                return { ...prev, holidays: [...prev.holidays, date] };
            }
        }
    });
  }, []);

  const projectionData = useMemo(() => {
    const data = [];
    const currentAttended = Math.max(0, state.totalClasses - state.absentClasses);
    const startPct = state.totalClasses === 0 ? 0 : (currentAttended / state.totalClasses) * 100;

    data.push({
      name: 'Now',
      attendAll: parseFloat(startPct.toFixed(1)),
      bunkAll: parseFloat(startPct.toFixed(1)),
    });

    for (let i = 1; i <= 7; i++) {
        const added = i * 6;
        const newTotal = state.totalClasses + added;
        const attendedIfAll = currentAttended + added;
        const attendedIfNone = currentAttended;

        data.push({
            name: `+${i}d`,
            attendAll: parseFloat(((attendedIfAll / newTotal) * 100).toFixed(1)),
            bunkAll: parseFloat(((attendedIfNone / newTotal) * 100).toFixed(1)),
        });
    }
    return data;
  }, [state.totalClasses, state.absentClasses]);

  const containerVariants = {
    hidden: { opacity: 0 },
    visible: { opacity: 1, transition: { staggerChildren: 0.1 } }
  };

  const itemVariants = {
    hidden: { y: 20, opacity: 0 },
    visible: { y: 0, opacity: 1 }
  };

  const attendedCount = Math.max(0, state.totalClasses - state.absentClasses);
  const attendanceInputValue = inputMode === 'absent' ? state.absentClasses : attendedCount;
  const customHolidaysCount = state.holidays.length;

  return (
    <div className="min-h-screen py-8 px-4 sm:px-6 md:py-16 md:px-12 max-w-7xl mx-auto overflow-x-hidden">
      <motion.div
        variants={containerVariants}
        initial="hidden"
        animate="visible"
        className="grid grid-cols-1 lg:grid-cols-2 gap-6 md:gap-10 lg:gap-12"
      >
        {/* Controls Section */}
        <motion.div variants={itemVariants} className="space-y-6 md:space-y-8">
          <div className="glass-panel p-6 sm:p-8 rounded-3xl neon-glow relative overflow-hidden group">
            <div className="absolute top-0 right-0 w-32 h-32 bg-cyan-500/10 rounded-full blur-3xl transform translate-x-16 -translate-y-16"></div>

            <h2 className="text-2xl md:text-3xl font-bold mb-8 text-white">Input Data</h2>

            <div className="space-y-6">
              <div className="space-y-2">
                <label className="text-slate-400 text-xs md:text-sm uppercase tracking-widest font-bold">Total Classes Held</label>
                <input
                  type="number"
                  inputMode="numeric"
                  min="0"
                  value={state.totalClasses || ''}
                  onChange={(e) => handleChange('totalClasses', parseInt(e.target.value) || 0)}
                  className="w-full bg-slate-900/40 border border-slate-700/50 rounded-2xl px-5 py-4 text-white focus:outline-none focus:border-cyan-500 transition-all text-lg"
                  placeholder="e.g. 120"
                />
              </div>

              <div className="space-y-2">
                <div className="flex justify-between items-center">
                    <label className="text-slate-400 text-xs md:text-sm uppercase tracking-widest font-bold">
                        {inputMode === 'absent' ? 'Classes Absent' : 'Classes Attended'}
                    </label>

                    <div className="bg-slate-950/80 p-1.5 rounded-xl flex text-xs font-semibold border border-slate-800">
                        <button
                            onClick={() => setInputMode('absent')}
                            className={`px-4 py-1.5 rounded-lg transition-all ${inputMode === 'absent' ? 'bg-red-500/20 text-red-300' : 'text-slate-500 hover:text-slate-400'}`}
                        >
                            Absent
                        </button>
                        <button
                            onClick={() => setInputMode('present')}
                            className={`px-4 py-1.5 rounded-lg transition-all ${inputMode === 'present' ? 'bg-cyan-500/20 text-cyan-300' : 'text-slate-500 hover:text-slate-400'}`}
                        >
                            Present
                        </button>
                    </div>
                </div>

                <input
                  type="number"
                  inputMode="numeric"
                  min="0"
                  max={state.totalClasses}
                  value={attendanceInputValue || ''}
                  onChange={(e) => handleAttendanceChange(parseInt(e.target.value) || 0)}
                  className={`w-full bg-slate-900/40 border border-slate-700/50 rounded-2xl px-5 py-4 text-white focus:outline-none transition-all text-lg ${inputMode === 'absent' ? 'focus:border-red-500/50' : 'focus:border-cyan-500/50'}`}
                  placeholder={inputMode === 'absent' ? "e.g. 15" : "e.g. 105"}
                />
              </div>

              <div className="space-y-2">
                <label className="text-slate-400 text-xs md:text-sm uppercase tracking-widest font-bold">Exam Start Date</label>
                <input
                  type="date"
                  value={state.examDate}
                  onChange={(e) => handleChange('examDate', e.target.value)}
                  className="w-full bg-slate-900/40 border border-slate-700/50 rounded-2xl px-5 py-4 text-white focus:outline-none focus:border-cyan-500 transition-all text-lg [color-scheme:dark]"
                />
              </div>

               <div className="space-y-2">
                  <div className="flex justify-between items-center mb-2">
                    <label className="text-slate-400 text-xs md:text-sm uppercase tracking-widest font-bold">Calendar</label>
                  </div>

                  <button 
                    onClick={() => setIsHolidayModalOpen(true)}
                    className="w-full bg-slate-900/40 border border-slate-700/50 hover:border-cyan-500/50 hover:bg-slate-800/40 rounded-2xl px-5 py-4 text-left flex justify-between items-center group transition-all"
                  >
                     <span className="text-slate-300 text-base truncate mr-2">
                        {customHolidaysCount === 0 && state.extraWorkingDays.length === 0 
                            ? "Configure Holidays" 
                            : `${customHolidaysCount} Holidays, ${state.extraWorkingDays.length} Working Weekends`}
                     </span>
                     <span className="text-cyan-500 bg-cyan-500/10 p-2 rounded-xl group-hover:bg-cyan-500/20 transition-colors">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" />
                        </svg>
                     </span>
                  </button>
               </div>
            </div>
          </div>
        </motion.div>

        {/* Analytics Section */}
        <motion.div variants={itemVariants} className="space-y-6 md:space-y-8">
          <div className="glass-panel p-6 sm:p-10 rounded-3xl relative overflow-hidden flex flex-col items-center justify-center text-center h-full min-h-[400px]">
            <motion.div 
              className={`absolute -inset-20 rounded-full blur-[100px] opacity-30 transition-colors duration-1000 ${stats?.isSafe ? 'bg-cyan-500' : 'bg-red-500'}`}
              animate={{ scale: [1, 1.2, 1], rotate: [0, 180, 0] }}
              transition={{ duration: 15, repeat: Infinity, ease: 'easeInOut' }}
            />

            <h3 className="text-slate-400 font-bold mb-6 uppercase tracking-[0.2em] text-xs md:text-sm z-10 opacity-70">Current Status</h3>
            <div className="relative z-10 mb-6">
                <svg className="w-56 h-56 sm:w-64 sm:h-64 md:w-72 md:h-72 transform -rotate-90" viewBox="0 0 256 256">
                    <defs>
                      <filter id="glow-cyan" x="-50%" y="-50%" width="200%" height="200%">
                        <feDropShadow dx="0" dy="0" stdDeviation="6" floodColor="#22d3ee" />
                      </filter>
                      <filter id="glow-red" x="-50%" y="-50%" width="200%" height="200%">
                        <feDropShadow dx="0" dy="0" stdDeviation="6" floodColor="#f87171" />
                      </filter>
                    </defs>
                    <circle cx="128" cy="128" r="115" stroke="#0f172a" strokeWidth="18" fill="transparent" />
                    <motion.circle 
                        cx="128" cy="128" r="115" 
                        stroke={stats?.isSafe ? "#22d3ee" : "#f87171"} 
                        strokeWidth="18" 
                        fill="transparent"
                        strokeDasharray={2 * Math.PI * 115}
                        strokeLinecap="round"
                        initial={{ strokeDashoffset: 2 * Math.PI * 115 }}
                        animate={{ strokeDashoffset: 2 * Math.PI * 115 * (1 - (stats?.currentPercentage || 0) / 100) }}
                        transition={{ duration: 2, type: "spring", stiffness: 40, damping: 15 }}
                        style={{ filter: `url(#glow-${stats?.isSafe ? 'cyan' : 'red'})` }}
                    />
                </svg>
                <div className="absolute inset-0 flex flex-col items-center justify-center">
                    <span className="text-6xl sm:text-7xl md:text-8xl font-black text-white tracking-tighter tabular-nums drop-shadow-2xl">
                        <AnimatedCounter value={stats?.currentPercentage || 0} toFixed={1} />%
                    </span>

                    <AnimatePresence mode="wait">
                      <motion.span
                        key={stats?.isSafe ? 'safe' : 'danger'}
                        initial={{ opacity: 0, y: 10 }}
                        animate={{ opacity: 1, y: 0 }}
                        exit={{ opacity: 0, y: -10 }}
                        className={`mt-4 px-6 py-1.5 rounded-full text-xs font-black uppercase tracking-widest ${stats?.isSafe ? 'bg-cyan-500/20 text-cyan-300 border-cyan-500/30' : 'bg-red-500/20 text-red-300 border-red-500/30'} border`}
                      >
                          {stats?.isSafe ? 'Safe' : 'Danger'}
                      </motion.span>
                    </AnimatePresence>
                </div>
            </div>

            <div className="relative z-10 flex gap-8 text-sm font-bold">
                <div className="flex flex-col items-center">
                    <span className="text-cyan-400 text-lg tabular-nums font-black"><AnimatedCounter value={attendedCount} /></span>
                    <span className="text-[10px] text-slate-500 uppercase tracking-widest">Attended</span>
                </div>
                <div className="w-px h-10 bg-slate-800" />
                <div className="flex flex-col items-center">
                    <span className="text-red-400 text-lg tabular-nums font-black"><AnimatedCounter value={state.absentClasses} /></span>
                    <span className="text-[10px] text-slate-500 uppercase tracking-widest">Missed</span>
                </div>
            </div>
          </div>
        </motion.div>

        {/* Stats Grid */}
        <motion.div variants={itemVariants} className="col-span-1 lg:col-span-2 grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
            <div className="glass-panel p-8 rounded-3xl relative overflow-hidden group">
                <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity">
                    <svg className="w-12 h-12 text-green-400" fill="currentColor" viewBox="0 0 20 20"><path d="M11 3a1 1 0 10-2 0v1a1 1 0 102 0V3zM15.657 5.757a1 1 0 00-1.414-1.414l-.707.707a1 1 0 001.414 1.414l.707-.707zM18 10a1 1 0 01-1 1h-1a1 1 0 110-2h1a1 1 0 011 1zM5.05 6.464A1 1 0 106.464 5.05l-.707-.707a1 1 0 00-1.414 1.414l.707.707zM5 10a1 1 0 01-1 1H3a1 1 0 110-2h1a1 1 0 011 1zM8 16v-1a1 1 0 112 0v1a1 1 0 11-2 0zM13.536 14.95a1 1 0 011.414 0l.707.707a1 1 0 11-1.414 1.414l-.707-.707a1 1 0 010-1.414zM16.122 17.536L16.121 17.535l-.001-.001a1 1 0 111.414-1.414l.001.001.001.001a1 1 0 11-1.414 1.414zM4.929 16.364l.707.707a1 1 0 01-1.414 1.414l-.707-.707a1 1 0 011.414-1.414z" /></svg>
                </div>
                <h4 className="text-slate-500 text-xs font-black uppercase tracking-[0.2em] mb-4">Bunk Potential</h4>
                {stats?.hasExamDate ? (
                  <>
                    <div className="flex items-baseline gap-2">
                        <span className="text-5xl font-black text-white tabular-nums"><AnimatedCounter value={stats?.bunkableClasses || 0} /></span>
                        <span className="text-sm text-slate-500 font-bold">classes</span>
                    </div>
                    <p className="text-sm text-slate-400 mt-4 leading-relaxed font-medium">
                        You can skip <span className="text-cyan-400 font-black"><AnimatedCounter value={stats?.bunkableDays || 0} /> full days</span> safely.
                    </p>
                  </>
                ) : (
                  <p className="text-sm text-slate-600 italic font-medium">Enter exam date to calculate bunkability.</p>
                )}
            </div>

            <div className="glass-panel p-8 rounded-3xl relative overflow-hidden group">
                <h4 className="text-slate-500 text-xs font-black uppercase tracking-[0.2em] mb-4">
                  {stats?.hasExamDate ? (stats?.isPossibleToReachTarget ? 'Requirement' : 'Terminal Alert') : 'Immediate Requirement'}
                </h4>
                {(!stats?.hasExamDate || stats?.isPossibleToReachTarget) ? (
                  <>
                    <div className="flex items-baseline gap-2">
                        <span className="text-5xl font-black text-white tabular-nums"><AnimatedCounter value={stats?.requiredClasses || 0} /></span>
                        <span className="text-sm text-slate-500 font-bold">classes</span>
                    </div>
                    <p className="text-sm text-slate-400 mt-4 leading-relaxed font-medium">
                        Must attend <span className="text-purple-400 font-black"><AnimatedCounter value={stats?.requiredDays || 0} /> full days</span> to hit 75%.
                    </p>
                  </>
                ) : (
                  <>
                    <div className="flex items-baseline gap-2">
                        <span className="text-5xl font-black text-red-500 tabular-nums"><AnimatedCounter value={stats?.maxAchievablePercentage || 0} toFixed={1} />%</span>
                    </div>
                    <p className="text-sm text-red-400/70 mt-4 leading-relaxed font-bold uppercase tracking-tighter">
                        75% is unreachable before the exam period.
                    </p>
                  </>
                )}
            </div>

            <div className="glass-panel p-8 rounded-3xl relative overflow-hidden group sm:col-span-2 lg:col-span-1">
                <h4 className="text-slate-500 text-xs font-black uppercase tracking-[0.2em] mb-4">Tomorrow Risk</h4>
                <div className="flex items-baseline gap-2">
                    <span className={`text-5xl font-black tabular-nums ${(stats?.tomorrowImpact || 0) < 75 ? 'text-red-500' : 'text-orange-400'}`}>
                        <AnimatedCounter value={stats?.tomorrowImpact || 0} toFixed={1} />%
                    </span>
                </div>
                <p className="text-sm text-slate-400 mt-4 leading-relaxed font-medium">
                    Projected drop if you miss all classes tomorrow.
                </p>
            </div>
        </motion.div>

        {/* Projection Chart Section */}
        <motion.div variants={itemVariants} className="col-span-1 lg:col-span-2">
            <div className="glass-panel p-6 sm:p-10 rounded-3xl relative overflow-hidden">
                <h3 className="text-slate-400 font-bold mb-10 uppercase tracking-[0.2em] text-xs md:text-sm text-center">7-Day Trajectory Forecast</h3>
                <div className="h-[250px] sm:h-[350px] w-full">
                    <ResponsiveContainer width="100%" height="100%">
                        <AreaChart data={projectionData} margin={{ top: 10, right: 10, left: -15, bottom: 0 }}>
                            <defs>
                                <linearGradient id="colorCyan" x1="0" y1="0" x2="0" y2="1">
                                    <stop offset="5%" stopColor="#22d3ee" stopOpacity={0.2}/>
                                    <stop offset="95%" stopColor="#22d3ee" stopOpacity={0}/>
                                </linearGradient>
                                <linearGradient id="colorRed" x1="0" y1="0" x2="0" y2="1">
                                    <stop offset="5%" stopColor="#f87171" stopOpacity={0.2}/>
                                    <stop offset="95%" stopColor="#f87171" stopOpacity={0}/>
                                </linearGradient>
                            </defs>
                            <CartesianGrid strokeDasharray="1 5" stroke="#1e293b" vertical={false} />
                            <XAxis dataKey="name" stroke="#475569" fontSize={11} tickLine={false} axisLine={false} tickMargin={10} />
                            <YAxis stroke="#475569" fontSize={11} tickLine={false} axisLine={false} domain={[0, 100]} tickFormatter={(value) => `${value}%`} />
                            <Tooltip contentStyle={{ backgroundColor: '#020617', borderColor: '#1e293b', borderRadius: '16px', color: '#f8fafc', fontSize: '12px' }} cursor={{ stroke: '#334155' }} />
                            <ReferenceLine y={75} stroke="#334155" strokeDasharray="3 3" />
                            <Area type="monotone" dataKey="attendAll" name="Perfect Attendance" stroke="#22d3ee" fillOpacity={1} fill="url(#colorCyan)" strokeWidth={3} />
                            <Area type="monotone" dataKey="bunkAll" name="Full Bunk" stroke="#f87171" fillOpacity={1} fill="url(#colorRed)" strokeWidth={3} />
                        </AreaChart>
                    </ResponsiveContainer>
                </div>
            </div>
        </motion.div>
      </motion.div>

      <Modal isOpen={isHolidayModalOpen} onClose={() => setIsHolidayModalOpen(false)} title="Attendance Calendar">
        <Calendar holidays={state.holidays} extraWorkingDays={state.extraWorkingDays} onDateToggle={toggleHoliday} />
      </Modal>
    </div>
  );
};
